  {
    "id": "c001",
    "name": "I. Amended information",
    "text": "I, The State of Indiana agrees to file an amended information adding Count If, Domestic Battery, Class A Misdemeanor, to which the Defendant does not object,"
  },
  {
    "id": "c002",
    "name": "Completion responsibility",
    "text": "As a Specific condition, it is the responsibility of the Defendant to show the Prosecutor’s Office that he has completed all the terms of this agreement"
  },
  {
    "id": "c003",
    "name": "Noncompliance and resumed prosecution",
    "text": "Defendant Specifically acknowledges that if he fails to comply, this case WH! be redocketed for court and Brosecution resum ed."
  },
  {
    "id": "c004",
    "name": "III. Speedy-trial waiver",
    "text": "QT, DEFENDANT'S WAIVER OF CONSTITUTIONAL RIGHTS: Program. Defendant specifically waives the tight to a speedy trial, and waives the time limits set by Criminal Rule 4 of the Indiana Rules of Criminal Procedure."
  },
  {
    "id": "c005",
    "name": "III. Jury-trial waiver",
    "text": "The Defendant waives his tight to a trial by jury On the charge(s) Jn this."
  },
  {
    "id": "c006",
    "name": "III. Judge-trial condition",
    "text": "\"Casey etees that it thé vent that the Defend, fails to comply with the terms of this Program and prosecution IS resumed, that any FRIAL IN THIS CASE SHALT, BE TRIAL BY A JUDGE."
  },
  {
    "id": "c007",
    "name": "IV.A. Identity stipulation",
    "text": "IV; TRE DEFENDANT HEREBY STIPULATES TO THE FOLLOWING: A. That he is the person referred to in the Charging Information in this case,"
  },
  {
    "id": "c008",
    "name": "IV.B. County stipulation",
    "text": "That the offense in this case occurred in St. Joseph County, Indiana."
  },
  {
    "id": "c009",
    "name": "IV.C. Conduct and injury stipulation",
    "text": "The Defendant Stipulates and agrees that on December 31, 2010, he knowingly touched Beth Marriott, a Person with whom he has a child in common, in a rude, insolent Or angry manner, and that this touching resulted in bodily injury to her."
  },
  {
    "id": "c010",
    "name": "IV.C. Argument admission",
    "text": "Specifically, the Defendant admits that he and the victim got into an argument and"
  },
  {
    "id": "c011",
    "name": "A. Fees and costs",
    "text": "THE DEFENDANT AGRERS TO; A, Pay a $170.00 user fee and $158.00 in court Costs as instructed at the time of signing this agreement. Payment in full due by. March 11,2011,"
  },
  {
    "id": "c012",
    "name": "B. No criminal offenses",
    "text": "Not commit any criminal offense during the “ten of this agreement."
  },
  {
    "id": "c013",
    "name": "C. Treatment evaluation",
    "text": "Undergo an evaluation for treatment and/or counseling with an approved agency,"
  },
  {
    "id": "c014",
    "name": "C. Counseling and information release",
    "text": "Defendant further agrees to participate in any counseling recommended and to sign a release of information form, so the Office of the Prosecuting Attormey can monitor the Defendant's Participation,"
  },
  {
    "id": "c015",
    "name": "C. Proof-of-evaluation deadline",
    "text": "Proof of evaluation must be made by March 11, 2011."
  },
  {
    "id": "c016",
    "name": "C. Evaluation-information access",
    "text": "Any evaluation and counseling information would be reviewable by the Prosecutor to determine Compliance, but would not otherwise be available fo the ‘public or for publication."
  },
  {
    "id": "c017",
    "name": "D. Community service",
    "text": "Defendant agrees to complete 60 hours of Community Service by August 3, 2011."
  },
  {
    "id": "c018",
    "name": "E. Reporting and cooperation",
    "text": "E. Report to the St, Joseph County Prosecutor’s Office as may be directed at reasonable times AND to answer all reasonable inquires posed by the Prosecutor’s Office and all Law Enforcement Agencies, including information conceming the allegations in this case,"
  },
  {
    "id": "c019",
    "name": "E. Information-use limitation",
    "text": "This information will not be used against Defendant if this cause ls redacketed and prosecution is resumed,"
  },
  {
    "id": "c020",
    "name": "F. Notice of changes",
    "text": "F, Notify the St, Joseph Prosecutor’s Office IN WRITING of any changes in address, phone number, and/or employment WITHIN SEVEN DAYS of any such changes,"
  },
  {
    "id": "c021",
    "name": "Pretrial Diversion dismissal date",
    "text": "The date by which the Defendant is fo be dismissed from the Pretrial Diversion Program is the 10™ day of February, 2012."
  },
  {
    "id": "c022",
    "name": "Compliance acknowledgment and revocation",
    "text": "Having read and signed the above agreement I understand that J must comply with all the _ Coriditions Set forth by the dates indieated: that no reminders will be sent: and that if] fail to comply, this agreement will automatically be revoked and a summons to appear in Court will be issued."
  }
]

